package com.giovannielena.restaurant.service;
import com.giovannielena.restaurant.dto.OrderDtos.*; import com.giovannielena.restaurant.entity.*; import com.giovannielena.restaurant.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class OrderService { private final OrderRepository orders; private final FoodItemRepository foods; private final UserRepository users; private final AddressRepository addresses;
 public OrderService(OrderRepository orders,FoodItemRepository foods,UserRepository users,AddressRepository addresses){this.orders=orders;this.foods=foods;this.users=users;this.addresses=addresses;}
 @Transactional public Order create(String email,CreateOrderRequest r){ User u=users.findByEmail(email).orElseThrow(); Order o=new Order(); o.setUser(u); o.setOrderType(Order.OrderType.valueOf(r.orderType().toUpperCase())); o.setSpecialInstructions(r.specialInstructions()); if(r.addressId()!=null)o.setAddress(addresses.findByIdAndUserId(r.addressId(),u.getId()).orElseThrow(()->new IllegalArgumentException("Address not found"))); BigDecimal total=BigDecimal.ZERO; for(ItemRequest i:r.items()){FoodItem f=foods.findById(i.foodId()).orElseThrow(()->new IllegalArgumentException("Food item not found: "+i.foodId())); if(!f.isAvailable())throw new IllegalArgumentException("Food item unavailable: "+f.getName()); OrderItem item=new OrderItem(); item.setOrder(o);item.setFood(f);item.setQuantity(i.quantity());item.setUnitPrice(f.getPrice());o.getItems().add(item);total=total.add(f.getPrice().multiply(BigDecimal.valueOf(i.quantity())));} o.setTotalAmount(total); return orders.save(o); }
 public List<Order> mine(String email){return orders.findByUserIdOrderByCreatedAtDesc(users.findByEmail(email).orElseThrow().getId());}
}